def gen(rng):
    def fmt(n, ts):
        return '%d %d\n%s' % (n, len(ts), ' '.join(map(str, ts)))
    tests = [fmt(1, [1]), fmt(1, [5, 9]), fmt(5, [3]), fmt(4, [2, 2, 2, 2]), fmt(7, [1, 100]),
             fmt(3, [1, 2]), fmt(10, [1, 3, 5, 7, 8]), fmt(3, [3, 4, 8])]
    for m in (1, 2, 3, 5, 8, 12):
        for _ in range(2):
            ts = [rng.randint(1, 12) for _ in range(m)]
            tests.append(fmt(rng.randint(1, 60), ts))
    for _ in range(3):
        ts = [rng.randint(1, 10**7) for _ in range(rng.randint(3, 10))]
        tests.append(fmt(rng.randint(1, 50), ts))
    tests.append(fmt(10**9, [rng.randint(1, 10**7) for _ in range(100000)]))
    tests.append(fmt(10**9, [10**7] * 100000))
    tests.append(fmt(10**9, [rng.randint(10**6, 10**7) for _ in range(100)]))
    tests.append(fmt(10**9, [rng.randint(9 * 10**6, 10**7) for _ in range(100000)]))
    return tests
